graphql.query:
query MailyardRoutingRejections($zone: string!, $from: Date!, $to: Date!) {
  viewer {
    zones(filter: { zoneTag: $zone }) {
      emailRoutingAdaptiveGroups(filter: { date_geq: $from, date_leq: $to }, limit: 5000) {
        count
        dimensions { status dmarc spf }
      }
    }
  }
}
